import {characterPresent} from './character-stats.js';
import {wetWeather} from './weather.js';
import {personalEventPosition} from './personal-event-presence.js';
import {contact,displayName,seePeople,introduce} from './identity.js';
import {relationship,changeRelationship} from './dialogue.js';
import {advanceFreeTime} from './free-roam.js';
export const dogyeomStories={
 dogyeom:{person:'dogyeom',episode:1,title:'굴러온 농구공',intro:'발치로 굴러온 공을 멈춘다. 초록색 재킷을 입은 학생이 손을 들며 다가온다.',opening:'아, 감사합니다. 손에서 빠졌네요. 혹시 어디 부딪히진 않았어요?',options:[['pass','공을 건네며 괜찮다고 답한다.','다행이다. 잘하는 척은 다 했는데 공부터 놓치네요. 하하.'],['introduce','공을 돌려주고 자연스럽게 서로 소개한다.','저는 윤도겸이에요. 경영학과 2학년이요. 수업 끝나고 잠깐 나온 거예요.'],['watch','혼자 연습 중이었는지 묻는다.','친구가 아직 안 와서요. 잘 기다리는 편인 줄 알았는데 손은 가만히 못 있네요.']],second:[['names','헤어지기 전에 서로 이름을 묻는다.','저 윤도겸이에요. 경영학과 2학년이요. 다음에 보면 먼저 인사해도 되죠?'],['leave','다음에 마주치면 인사하기로 하고 돌아간다.','공 잡아줘서 고마워요. 다음엔 이렇게 굴러가게 안 할게요.']]},
 'dogyeom:2':{person:'dogyeom',episode:2,previous:'dogyeom',title:'잘할 것 같은 사람',intro:'초록색 재킷의 학생이 휴대폰 메시지를 읽다가 길게 숨을 내쉰다.',opening:'덩치 크면 발표도 안 떨 것 같대요. 그게 무슨 상관인지 모르겠는데. 제가 또 그냥 맡는다고 했고요.',options:[['ask','발표에서 어떤 부분이 어려운지 먼저 묻는다.','첫 문장이요. 시작하고 나면 괜찮은데, 다 저만 보고 있는 그 순간이 좀.'],['practice','원하면 첫 문장만 들어주겠다고 제안한다.','진짜요? 그럼 웃지 말기예요. 아니, 이상하면 웃어도 되는데 이유는 알려줘요.'],['assume','자신 있게 하면 쉬울 거라고 말한다.','그게 마음대로 되면 벌써 했죠. 아, 화내는 건 아니고요. 조금 막막해서.']],second:[['listen','본인이 원하는 만큼만 연습하고 마친다.','처음만 넘기면 된다고 생각하니까 덜 무섭네요. 고마워요.'],['split','팀원에게 나눠 맡길 부분을 스스로 정하게 기다린다.','제가 다 한다고 말한 걸 제가 바꿔야겠죠. 오늘은 그 말부터 해볼게요.']]},
 'dogyeom:3':{person:'dogyeom',episode:3,previous:'dogyeom:2',title:'오늘은 구경하는 쪽',intro:'공을 옆에 내려놓은 학생이 벤치의 빈자리를 손으로 가리킨다.',opening:'오늘은 안 뛰려고요. 어제 좀 무리했나 봐요. 저도 쉬는 날은 있어요. 의외라는 얼굴 하지 마요.',options:[['rest','쉬기로 한 결정을 존중하고 잠깐 이야기를 듣는다.','몸이 쉬자는데 제가 계속 우기면 안 되죠. 이 말 남한테는 잘했는데.'],['share','나도 운동을 쉬기 어려울 때가 있다고 털어놓는다.','아, 진짜요? 저만 그런 줄 알았는데. 가만있으면 뒤처지는 느낌이 들 때가 있거든요.'],['tease','오늘은 공보다 벤치와 친해지는 날이냐고 웃는다.','그렇게 말하니까 좀 쑥스럽네요. 벤치랑은 아직 어색해요.']],second:[['quiet','무리한 운동 대신 잠깐 같이 쉬다가 돌아간다.','오늘 아무것도 안 했다는 생각은 안 드네요. 같이 쉬어서 그런가.'],['thanks','지난번 발표 준비는 어땠는지 묻고 이야기를 마친다.','첫 문장은 덜 떨었어요. 팀원들한테도 나눠 달라고 했고요. 다음엔 저도 들어줄게요.']]}
};
export function dogyeomLocation(s){const m=s.clock.minute;if(m>=720&&m<780)return 'cafeteria';if(m>=960&&m<1020)return 'library';if(m>=1020&&m<=1170)return wetWeather(s)?'gym':'outdoorCourt';return null;}
function dogyeomTime(s,minutes){return s.clock.minute+minutes<=1200&&!(s.appointments??[]).some(a=>a.status==='pending'&&a.day===s.day&&a.minute>=s.clock.minute&&a.minute<s.clock.minute+minutes);}
export function dogyeomEventsAt(s,place){if(!characterPresent(s,'dogyeom'))return [];if(s.academics?.registrationPending||s.freeDay?.home)return [];return Object.entries(dogyeomStories).filter(([id,d])=>{const r=s.personalEvents?.records?.[id],prior=s.personalEvents?.records?.[d.previous];return r?.status!=='completed'&&(!d.previous||prior?.status==='completed'&&s.day>prior.completedDay)&&dogyeomTime(s,r?.stage?20:30)&&(personalEventPosition(s,'dogyeom')??dogyeomLocation(s))===place&&(d.episode===1?place==='outdoorCourt'||place==='gym':true);}).map(([eventId,d])=>({eventId,person:'dogyeom',title:contact(s,'dogyeom').introduced?d.title:'초록색 재킷을 입은 학생',resuming:s.personalEvents?.records?.[eventId]?.status==='paused'}));}
export function beginDogyeomEvent(state,id){if(!dogyeomEventsAt(state,state.location).some(e=>e.eventId===id))throw new Error('지금은 같은 장소에서 만날 수 없습니다.');const s=structuredClone(state);s.personalEvents??={records:{}};const store=s.personalEvents,old=store.records[id],active=store.records[store.active];if(active?.status==='active'&&store.active!==id)active.status='paused';store.records[id]={...old,eventId:id,person:'dogyeom',episode:dogyeomStories[id].episode,status:'active',stage:old?.stage??0,choices:old?.choices??[],location:s.location,day:s.day,until:s.clock.minute+(old?.stage?20:30)};store.active=id;seePeople(s,['dogyeom']);return s;}
export function dogyeomEventView(s){const r=s.personalEvents.records[s.personalEvents.active],d=dogyeomStories[r.eventId];return {...d,...r,title:contact(s,'dogyeom').introduced?d.title:'초록색 재킷을 입은 학생',options:r.status==='completed'?[]:(r.stage&&!contact(s,'dogyeom').introduced?[...d.second.filter(o=>o[0]!=='names').slice(0,1),dogyeomStories.dogyeom.second[0]]:r.stage?d.second.filter(o=>!contact(s,'dogyeom').introduced||o[0]!=='names'):d.options).map(o=>o.slice(0,2))};}
export function progressDogyeomEvent(state,choice){const r=state.personalEvents.records[state.personalEvents.active],d=dogyeomStories[r.eventId],option=(r.stage?[...d.second,...(!contact(state,'dogyeom').introduced?[dogyeomStories.dogyeom.second[0]]:[])]:d.options).find(o=>o[0]===choice),minutes=r.stage?20:10;if(!option||r.status!=='active'||r.day!==state.day||r.location!==state.location||state.clock.minute+minutes>r.until||!dogyeomTime(state,minutes))throw new Error('현재 장소와 선택을 다시 확인해 주세요.');const s=advanceFreeTime(state,minutes),rec=s.personalEvents.records[r.eventId];rec.choices.push(choice);if(['introduce','names'].includes(choice)){introduce(s,'dogyeom','personal-event');s.contacts.dogyeom.details={major:'경영학과',year:2};}seePeople(s,['dogyeom']);const tense=relationship(s,'dogyeom').tension>=3;rec.last={player:option[1],text:tense&&choice==='tease'?'오늘은 그런 농담 듣기 좀 그렇네요. 그냥 잠깐 쉬고 싶어요.':option[2]};changeRelationship(s,'dogyeom','taei',choice==='assume'?{tension:1}:{familiarity:1,trust:1});if(r.stage){rec.status='completed';rec.completedDay=s.day;rec.completedMinute=s.clock.minute;rec.result=option[1]+' '+rec.last.text;s.lastResult=rec.result;s.memory.push(`[${s.day}일차] ${displayName(s,'dogyeom')} · ${d.title}: ${rec.result}`);if(!s.known.includes(d.title+' 기록'))s.known.push(d.title+' 기록');}else rec.stage=1;s.pace={count:0,seen:{}};return s;}
